svg.script:
// THE INTERFACE CARRIER — inline mirror of rosetta/src/grammar/interface.ts,
// kept inline so this stays one self-contained SVG (no imports, no bundler).
var CARRIER = {
  Proxy: Proxy,
  Reflect: Reflect,
  // Catch carries an outcome instead of swallowing the exception
  "catch": function (run) {
    try { return { ok: true, value: run() }; }
    catch (error) { return { ok: false, error: error }; }
  },
  // a tagged template preserves the literal strings separately from its values
  template: function (strings) {
    var values = Array.prototype.slice.call(arguments, 1);
    return Object.freeze({
      strings: strings, raw: strings.raw, values: Object.freeze(values.slice()),
      text: String.raw.apply(null, [{ raw: strings.raw }].concat(values))
    });
  }
};

// Prompt prompts the universe; any query binds a root complex.
// Modeled on main() + try/catch/finally: carrier in, templates out.
function Prompt(io) {
  var tpl = io.template, Catch = io["catch"], Reflect_ = io.Reflect, Proxy_ = io.Proxy;
  var bound = false;
  try {
    // the root complex (the universe's invariants), read from the CDATA tree
    var base = JSON.parse(document.getElementById('root-data').textContent);
    // accessed through a Proxy so any lens path is resolvable — always extendable
    var root = new Proxy_(base, {
      get: function (t, k, r) { return (k in t) ? Reflect_.get(t, k, r) : undefined; }
    });
    var period = root.law.period, i = 0, clock = document.getElementById('clock');
    // the stepper: RangeError is the range that says no
    function at(n) {
      if (!(Number.isInteger(n) && n >= 0 && n < period))
        throw new RangeError('step ' + n + ' out of [0,' + period + ')');
      return root.cycle[n];
    }
    function tick() {
      var res = Catch(function () { return at(i % period); }); // CatchResult {ok,value}|{ok,error}
      var f = res.ok ? res.value : at(0);
      // the story as a template: literals are the form, ${values} the reference
      var line = tpl`step ${f.step} · ${f.state} · ${f.color} · K=${root.law.K}`;
      clock.textContent = line.text;
      for (var k = 0; k < period; k++) {
        var hl = document.getElementById('hl' + k);
        if (hl) hl.setAttribute('opacity', k === (i % period) ? '0.9' : '0');
      }
      i++;
    }
    bound = true; tick(); setInterval(tick, 750);
    // stage 4 swaps the interval for an OfflineAudioContext clock + a VTTCue track.
  } catch (e) {
    // the boundary: SMIL still animates (progressive enhancement if JS is off)
  } finally {
    // always runs: the universe reports whether Prompt bound the root complex
    document.documentElement.setAttribute('data-prompt', bound ? 'bound' : 'smil-only');
  }
}

Prompt(CARRIER);
